
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_lb07_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_lb07", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.560209033577594e+00, -3.484484468611455e+00, -3.378354491065480e+00, -3.231292835001244e+00, -3.030807984195521e+00, -2.763782886267775e+00, -2.419712394968666e+00, -1.996666155844503e+00, -1.510145660721531e+00, -1.004831560412366e+00, -5.823532305673144e-01, -4.185562566141680e-01, -3.534180698850166e-01, -2.532124804197005e-01, -1.311094008577323e-01, -3.421074455911962e-02, 2.131705667848077e-03, -8.616830518347646e-04, -7.287372214140477e-05, -1.747339745112278e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


